action.validator:
c = ql.newCond();
ql.cond.in(c,"applyStatus",tuple("CONFIRMING_SIGNUP" , "SUCCESS_SIGNUP"));
ql.cond.eq(c,"applyId",$rec["applyId"]);
existRec = ql.query("SouReqApply",c);
return ql.gt(count(existRec),0);

c = ql.newCond();
ql.cond.eq(c,"status","APPROVED");
ql.cond.eq(c,"reqHeadId",$rec["reqHeadId"]);
existRec = ql.query("SouReqHeadBuyer",c);
return ql.gt(count(existRec),0);


c = ql.newCond();
ql.cond.gt(c,"publicEndTime",$rec["publicEndTime"]);
ql.cond.eq(c,"reqHeadId",$rec["reqHeadId"]);
existRec = ql.query("SouReqHeadBuyer",c);
return ql.le(count(existRec),0);

c = ql.newCond();
ql.cond.notIn(c,"applyStatus",tuple("NO_SIGNUP","WITHDRAW","FAIL_SIGNUP"));
ql.cond.eq(c,"vendorId",$rec["vendorId"]);
ql.cond.eq(c,"reqHeadId",$rec["reqHeadId"]);
existRec = ql.query("SouReqApply",c);
return ql.le(count(existRec),0);

c = ql.newCond();
ql.cond.notEq(c,"applyId",$rec["applyId"]);
ql.cond.eq(c,"vendorId",$rec["vendorId"]);
ql.cond.eq(c,"reqHeadId",$rec["reqHeadId"]);
existRec = ql.query("SouReqApply",c);
return ql.le(count(existRec),0);
